<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { api, DEFAULT_HOURS } from '../utils/api'
import { themeState } from '../composables/useTheme'
import { useServerSocket } from '../composables/useServerSocket'
import { bytes, percent, rate, uptime, parseGpu, displayPing, online } from '../utils/format'
import HistoryChart from '../components/HistoryChart.vue'
const props = defineProps({ id: String }); const router = useRouter(); const server = ref(null); const history = ref([]); const hours = ref(DEFAULT_HOURS); const loading = ref(true); const error = ref('')
function merge(patch) { server.value = { ...server.value, ...patch } }
const socket = useServerSocket(String(props.id), () => [props.id], (message) => { (message.updates || []).forEach((u) => { const sample = u.samples?.at(-1); const data = sample?.data || sample?.payload || sample?.metrics; if (data) merge(data) }) }, Number(themeState.config?.frontend_ws_timeout_minutes || 0))
async function load(restHistory = true) { loading.value = true; try { const result = await api.server(props.id); server.value = result.server || result.data || result; if (restHistory) { const resultHistory = await api.history(props.id, hours.value); history.value = resultHistory.history || resultHistory.data || resultHistory || [] } } catch (e) { error.value = e.message } finally { loading.value = false } }
async function changeHours() { const result = await api.history(props.id, hours.value); history.value = result.history || result.data || result || [] }
async function visibility() { if (document.hidden) socket.stop(); else { await load(false); socket.reconnect() } }
onMounted(async () => { await load(); socket.start(); document.addEventListener('visibilitychange', visibility) }); onBeforeUnmount(() => { socket.stop(); document.removeEventListener('visibilitychange', visibility) })
const gpu = computed(() => parseGpu(server.value?.gpu_info)); const disk = computed(() => server.value?.disk)
</script>
<template><section class="page detail-page"><button class="back-button" @click="router.push('/')">← All servers</button><div v-if="loading" class="loading-state"><span class="spinner" /> Loading server…</div><div v-else-if="error" class="notice error">{{ error }}</div><template v-else-if="server"><div class="detail-head"><div><p class="eyebrow">SERVER DETAILS</p><h1>{{ server.name || server.hostname || `Server ${id}` }}</h1><p class="subtitle">{{ server.os_name || server.os || 'Unknown OS' }} · {{ server.ip_v4 || server.ipv4 || 'No public IPv4' }}</p></div><span class="status-pill large" :class="online(server) ? 'online' : 'offline'">{{ online(server) ? 'Online' : 'Offline' }}</span></div><div class="metric-grid large-metrics"><div><span>CPU usage</span><strong>{{ percent(server.cpu ?? server.cpu_usage) }}</strong></div><div><span>Memory</span><strong>{{ percent(server.ram_percent ?? server.memory_percent) }}</strong></div><div><span>Download</span><strong>{{ rate(server.net_in ?? server.network_in) }}</strong></div><div><span>Upload</span><strong>{{ rate(server.net_out ?? server.network_out) }}</strong></div><div><span>Uptime</span><strong>{{ server.uptime_human || uptime(server.uptime) }}</strong></div></div><div class="panel history-panel"><div class="panel-head"><div><h2>Performance history</h2><p>Samples from the selected window</p></div><select v-model="hours" @change="changeHours"><option value="0.167">Last 10 minutes</option><option value="0.5">Last 30 minutes</option><option value="1">Last hour</option><option value="6">Last 6 hours</option><option value="12">Last 12 hours</option><option value="24">Last 24 hours</option><option value="48">Last 2 days</option><option value="96">Last 4 days</option><option value="168">Last 7 days</option></select></div><div class="chart-grid"><div><h3>CPU</h3><HistoryChart :rows="history" field="cpu" color="#7c5cff" /></div><div><h3>Memory</h3><HistoryChart :rows="history" field="ram_percent" color="#14b8a6" /></div><div><h3>Network in</h3><HistoryChart :rows="history" field="net_in" color="#f59e0b" /></div><div><h3>Network out</h3><HistoryChart :rows="history" field="net_out" color="#ef4444" /></div><div><h3>Ping (CT)</h3><HistoryChart :rows="history" field="ping_ct" color="#8b5cf6" /></div><div><h3>Loss (CT)</h3><HistoryChart :rows="history" field="loss_ct" color="#ef4444" /></div></div></div><div class="detail-columns"><div class="panel"><div class="panel-head"><h2>Network probes</h2></div><div class="probe-list"><div v-for="key in ['ct','cu','cm','bgp']" :key="key"><span>{{ key.toUpperCase() }}</span><strong>{{ displayPing(server.ping?.[key]) || '—' }}</strong><em>{{ percent(server.loss?.[key]) }} loss</em></div></div></div><div v-if="disk" class="panel"><div class="panel-head"><h2>Disk I/O</h2></div><div class="probe-list"><div><span>Read</span><strong>{{ rate(disk.read ?? disk.read_bytes) }}</strong></div><div><span>Write</span><strong>{{ rate(disk.write ?? disk.write_bytes) }}</strong></div></div></div><div v-if="gpu.length" class="panel"><div class="panel-head"><h2>GPU</h2></div><div class="gpu-list"><div v-for="item in gpu" :key="item.id"><span>{{ item.name || `GPU ${item.id}` }}</span><strong>{{ item.info || 'Available' }}</strong></div></div></div></div></template></section></template>
